const W_=W,H_=H;const lights=[];for(let i=0;i<26;i++){lights.push({x:Math.random()*W_(),y:Math.random()*H_()*0.32,r:6+Math.random()*10,phase:Math.random()*Math.PI*2,speed:0.3+Math.random()*0.4,drift:(Math.random()-0.5)*0.15});}
const cream=[];for(let i=0;i<60;i++){cream.push({x:Math.random()*W_(),y:H_()*0.72+Math.random()*H_()*0.26,r:14+Math.random()*26,phase:Math.random()*Math.PI*2,speed:0.15+Math.random()*0.25,ox:(Math.random()-0.5)*40});}
let t=0;
function frame(){
 t+=0.012;
 const w=W_(),h=H_();
 ctx.clearRect(0,0,w,h);
 // верхние гаснущие огни
 for(const l of lights){
 const flick=0.35+0.3*Math.sin(t*l.speed+l.phase);
 const x=l.x+Math.sin(t*0.2+l.phase)*l.drift*20;
 const y=l.y+Math.cos(t*0.15+l.phase)*4;
 const grad=ctx.createRadialGradient(x,y,0,x,y,l.r*2.2);
 grad.addColorStop(0,'rgba(201,138,75,'+(0.55*flick)+')');
 grad.addColorStop(0.5,'rgba(232,217,181,'+(0.18*flick)+')');
 grad.addColorStop(1,'rgba(232,217,181,0)');
 ctx.fillStyle=grad;
 ctx.beginPath();
 ctx.arc(x,y,l.r*2.2,0,Math.PI*2);
 ctx.fill();
 }
 // нижняя кремовая волна из мягких бликов
 for(const c of cream){
 const rise=Math.sin(t*c.speed+c.phase)*10;
 const x=c.x+Math.sin(t*0.1+c.phase)*c.ox;
 const y=c.y+rise;
 const grad=ctx.createRadialGradient(x,y,0,x,y,c.r);
 grad.addColorStop(0,'rgba(232,217,181,0.5)');
 grad.addColorStop(0.6,'rgba(201,138,75,0.15)');
 grad.addColorStop(1,'rgba(232,217,181,0)');
 ctx.fillStyle=grad;
 ctx.beginPath();
 ctx.arc(x,y,c.r,0,Math.PI*2);
 ctx.fill();
 }
 // тонкая линия горизонта сумрака
 const hy=h*0.52;
 ctx.strokeStyle='rgba(31,43,74,0.12)';
 ctx.lineWidth=1.5;
 ctx.beginPath();
 ctx.moveTo(0,hy+Math.sin(t*0.3)*6);
 for(let x=0;x<=w;x+=40){
 ctx.lineTo(x,hy+Math.sin(t*0.3+x*0.01)*6);
 }
 ctx.stroke();
 requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
